        return

    n = tokens[0]
    capacity = tokens[1]
    weights = tokens[2:2+n]
    profits = tokens[2+n:2+2*n]

    dp = [0] * (capacity + 1)
    for i in range(len(weights)):
        w = weights[i]
        p = profits[i]
        for cap in range(capacity, w - 1, -1):
            if dp[cap - w] + p > dp[cap]:
                dp[cap] = dp[cap - w] + p

    print(dp[capacity])

