import java.util.*;

public class Solution {
    static int R, C;
    static int[][] grid;

    static void dfs(int r, int c) {
        if (r < 0 || r >= R || c < 0 || c >= C || grid[r][c] != 1) return;
        grid[r][c] = 0;
        dfs(r + 1, c);
        dfs(r - 1, c);
        dfs(r, c + 1);
        dfs(r, c - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        R = sc.nextInt();
        C = sc.nextInt();
        grid = new int[R][C];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        int count = 0;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (grid[i][j] == 1) {
                    count++;
                    dfs(i, j);
                }
            }
        }
        System.out.println(count);
    }
}

